    if(seen(t,'start')||seen(t,'complete')){row.result='本次进度已有提交记录，留待App核对';return;}
    const item=await itemFor(scope,t);if(!item){row.result='缺少浏览项目，留待App';return;}
    if(!/^https?:\/\/(?:[A-Za-z0-9-]+\.)*(?:jd\.com|jdpay\.com)(?::\d+)?(?:\/|$)/.test(item.itemId)&&!/^\d{1,24}$/.test(item.itemId)){row.result='浏览项目需App打开';return;}
